  if(m)return xlDay(`${m[1]}-${String(m[2]).padStart(2,"0")}-${String(m[3]).padStart(2,"0")}`);
  m=s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})/);
  if(m){let y=Number(m[3]);if(y<100)y+=2000;return xlDay(`${y}-${String(m[2]).padStart(2,"0")}-${String(m[1]).padStart(2,"0")}`)}
