    // counted twice when the duplicate's copy of it arrives.
    const erpSeen=new Set((logsByOrder.get(keep.id)||[]).filter(w=>w.userId===PRI_LOG_USER)
      .map(w=>w.serialId?`s|${w.serialId}|${w.stageId}`:`q|${w.stageId}`));
